id.content:
lemma mem (h : x ∈ l) : (𝗴𝗲(x) : Set F) ⊆ 𝗚𝗲(l) := by
  induction l with
  | nil => contradiction;
  | cons a as ih =>
    cases h;
    . tauto;
    . apply Set.subset_union_of_subset_right $ ih (by assumption);

